"use client";

/* ─────────────────────────────────────────────────────────
 * WHEEL PICKER: drums you can fling
 *
 *   drum      every column is a real cylinder: options sit on
 *             its faces and tip away into the dark as they
 *             leave the middle, one transform a frame
 *   lens      the middle row is a separate copy of the drum,
 *             clipped to the band, in full colour; a letter
 *             crossing the band's edge is half one, half the
 *             other, like glass over the wheel
 *   fling     drag and let go: the release speed is projected
 *             forward and the wheel decays onto a row, with a
 *             tick on phones for each row it passes; past the
 *             ends of a wheel that doesn't loop it stretches
 *   settle    the value is committed once the wheel rests, and
 *             a unit beside the lens morphs with it (1 hour,
 *             2 hours). Options that can't be chosen are dimmed
 *             and the wheel turns on past them
 *
 * Each wheel is a spinbutton: arrows step, Page Up and Down
 * jump five, Home and End go to the ends; a mouse notch moves
 * one row and taps on a row bring it to the middle.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { TextMorph } from "./text-morph";
import { useInteractionReducedMotion } from "./imported-ui-interaction-motion";
import { SLOTS, STEP, useWheelDrum } from "./use-wheel-drum";

export type WheelValue = string | number;
export type WheelOption<T extends WheelValue = WheelValue> =
  T | { value: T; label?: string; disabled?: boolean };

export interface WheelPickerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Row height in px; the drum's radius follows from it. */
  itemHeight?: number;
  /** Ticks on phones that can vibrate, one per row. */
  haptics?: boolean;
  children: React.ReactNode;
}

export interface WheelProps<T extends WheelValue = WheelValue> {
  options: readonly WheelOption<T>[];
  value?: NoInfer<T>;
  defaultValue?: NoInfer<T>;
  onValueChange?: (value: NoInfer<T>) => void;
  /** Turn past the end back to the start, like minutes. */
  loop?: boolean;
  /** What the wheel sets, for screen readers: "Hours". */
  label: string;
  /** Fixed beside the lens: "min", or a function for "1 hour" / "2 hours". */
  unit?: string | ((value: NoInfer<T>) => string);
  /** Where the options sit in their column. */
  align?: "start" | "center" | "end";
  className?: string;
  style?: React.CSSProperties;
}

const Ctx = React.createContext({ itemHeight: 36, haptics: true });
const PERSPECTIVE = 1000;

const valueOf = <T extends WheelValue>(o: WheelOption<T>) =>
  typeof o === "object" ? o.value : o;
const labelOf = <T extends WheelValue>(o: WheelOption<T>) =>
  typeof o === "object" ? (o.label ?? String(o.value)) : String(o);
const offOf = <T extends WheelValue>(o: WheelOption<T>) =>
  typeof o === "object" && Boolean(o.disabled);

export function WheelPicker({
  itemHeight = 36,
  haptics = true,
  className = "",
  style,
  children,
  ...props
}: WheelPickerProps) {
  const H = Math.max(28, Math.min(56, itemHeight));
  const radius = H / (2 * Math.tan((STEP / 2) * (Math.PI / 180)));
  const ctx = React.useMemo(() => ({ itemHeight: H, haptics }), [H, haptics]);
  return (
    <Ctx.Provider value={ctx}>
      <div
        role="group"
        className={`relative flex w-full select-none justify-center px-2 ${className}`}
        style={{ height: Math.round(radius * 2), ...style }}
        {...props}
      >
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-1/2 -translate-y-1/2 rounded-[11px] bg-muted"
          style={{ height: H }}
        />
        {children}
      </div>
    </Ctx.Provider>
  );
}

export function Wheel<T extends WheelValue = WheelValue>({
  options,
  value,
  defaultValue,
  onValueChange,
  loop = false,
  label,
  unit,
  align = "center",
  className = "",
  style,
}: WheelProps<T>) {
  const { itemHeight: H, haptics } = React.useContext(Ctx);
  const reduced = useInteractionReducedMotion();
  const count = options.length;
  const indexOf = (v: T | undefined) =>
    Math.max(
      0,
      options.findIndex((o) => valueOf(o) === v),
    );
  const [own, setOwn] = React.useState<T | undefined>(
    defaultValue ?? (count ? valueOf(options[0]) : undefined),
  );
  const current = value !== undefined ? value : own;
  const index = indexOf(current);

  const optionsRef = React.useRef(options);
  const report = React.useRef(onValueChange);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
    report.current = onValueChange;
  });
  const controlled = value !== undefined;
  const committed = React.useRef(index);

  const drum = useWheelDrum(index, {
    count,
    loop,
    itemHeight: H,
    reduced,
    haptics,
    label: (i) => labelOf(optionsRef.current[i]),
    disabled: (i) => offOf(optionsRef.current[i]),
    onRest: (i) => {
      if (i === committed.current) return;
      committed.current = i;
      const next = valueOf(optionsRef.current[i]);
      if (!controlled) setOwn(next);
      report.current?.(next);
    },
  });

  // The value changed from outside (another wheel clamped it, or the app set it): turn to it.
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (index === committed.current) return;
    committed.current = index;
    drum.turnTo(index, !reduced);
  }, [index]);

  // Labels or disabled options changed: relabel the faces in place.
  const labels = options
    .map((o) => `${labelOf(o)}${offOf(o) ? "·" : ""}`)
    .join("|");
  React.useEffect(() => {
    drum.repaint();
  }, [labels]);

  // Faces are labelled once here; the drum relabels them directly as it turns.
  const [faceText] = React.useState(() =>
    Array.from({ length: SLOTS }, (_, k) => {
      const i = k + SLOTS * Math.round((index - k) / SLOTS);
      const real = loop ? ((i % count) + count) % count : i;
      return count && (loop || (i >= 0 && i < count))
        ? labelOf(options[real])
        : "";
    }),
  );

  const unitOf = (v: T) =>
    typeof unit === "function" ? unit(v) : (unit ?? "");
  const unitText = current !== undefined && unit ? unitOf(current) : "";
  const widest = unit
    ? options
        .map((o) => unitOf(valueOf(o)))
        .reduce((a, b) => (b.length > a.length ? b : a), "")
    : "";

  const onKeyDown = (e: React.KeyboardEvent) => {
    const moves: Record<string, number> = {
      ArrowUp: -1,
      ArrowDown: 1,
      PageUp: -5,
      PageDown: 5,
    };
    if (e.key in moves) {
      e.preventDefault();
      drum.nudge(moves[e.key]);
    } else if (e.key === "Home" || e.key === "End") {
      e.preventDefault();
      const to = e.key === "Home" ? 0 : count - 1;
      drum.turnTo(to, !reduced);
    }
  };

  const justify =
    align === "start"
      ? "justify-start"
      : align === "end"
        ? "justify-end"
        : "justify-center";
  const faceClass = `absolute inset-x-0 flex items-center whitespace-nowrap px-2.5 tabular-nums [backface-visibility:hidden] data-[off]:opacity-35 ${justify}`;
  const face = (k: number) => ({
    top: -H / 2,
    height: H,
    transform: `rotateX(${-k * STEP}deg) translateZ(${drum.radius}px)`,
  });
  const edge = `calc(50% - ${H / 2}px)`,
    edge2 = `calc(50% + ${H / 2}px)`;
  // The drum fades toward its rim and leaves a hole where the lens copy sits.
  const mask = `linear-gradient(to bottom, transparent 8%, #000 36%, #000 ${edge}, transparent ${edge}, transparent ${edge2}, #000 ${edge2}, #000 64%, transparent 92%)`;
  // The first frame's rotation; after that the drum writes its own transform, so React must never touch it.
  const [current3d] = React.useState(() => ({
    transformStyle: "preserve-3d" as const,
    transform: `translateZ(${-drum.radius}px) rotateX(${index * STEP}deg)`,
  }));

  return (
    <div
      ref={(el) => drum.attachColumn(el)}
      role="spinbutton"
      tabIndex={0}
      aria-label={label}
      aria-valuenow={index}
      aria-valuemin={0}
      aria-valuemax={Math.max(0, count - 1)}
      aria-valuetext={`${count ? labelOf(options[index]) : ""}${unitText ? ` ${unitText}` : ""}`}
      onKeyDown={onKeyDown}
      className={`group relative flex h-full min-w-0 flex-1 cursor-grab touch-none items-center outline-none active:cursor-grabbing ${className}`}
      style={style}
    >
      <div
        className="relative h-full min-w-0 flex-1 tracking-[-0.01em]"
        style={{ fontSize: Math.round(H * 0.56) }}
      >
        <div
          aria-hidden="true"
          className="absolute inset-0 text-muted-foreground"
          style={{
            perspective: PERSPECTIVE,
            maskImage: mask,
            WebkitMaskImage: mask,
          }}
        >
          <div
            ref={(el) => drum.attachDrum(el)}
            className="absolute inset-x-0 top-1/2 h-0 will-change-transform"
            style={current3d}
          >
            {faceText.map((t, k) => (
              <span
                key={k}
                ref={(el) => drum.attachFace(k, el)}
                className={faceClass}
                style={face(k)}
              >
                {t}
              </span>
            ))}
          </div>
        </div>
        <div
          aria-hidden="true"
          className="absolute inset-x-0 top-1/2 -translate-y-1/2 overflow-hidden rounded-[11px] text-foreground group-focus-visible:ring-2 group-focus-visible:ring-ring/50"
          style={{ height: H, perspective: PERSPECTIVE }}
        >
          <div
            ref={(el) => drum.attachLens(el)}
            className="absolute inset-x-0 top-1/2 h-0 will-change-transform"
            style={current3d}
          >
            {faceText.map((t, k) => (
              <span
                key={k}
                ref={(el) => drum.attachLensFace(k, el)}
                className={faceClass}
                style={face(k)}
              >
                {t}
              </span>
            ))}
          </div>
        </div>
      </div>
      {unit && (
        <span
          aria-hidden="true"
          className="relative grid shrink-0 pr-2.5 text-[14px] font-medium text-foreground"
        >
          <span className="invisible col-start-1 row-start-1 whitespace-nowrap">
            {widest}
          </span>
          <span className="col-start-1 row-start-1 whitespace-nowrap">
            <TextMorph animateWidth={false}>{unitText}</TextMorph>
          </span>
        </span>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/*
 * One wheel's motion engine. The options sit on a ring of SLOTS faces round a cylinder; turning
 * the wheel is one rotateX on the drum (and the same on its copy in the lens), so a fling costs two
 * transforms a frame. Only faces turning round the back are relabelled, so a wheel of 60 minutes or
 * 200 years still has 18 faces. Nothing renders through React while it turns: the value is committed
 * once the wheel comes to rest.
 *
 *   drag     follows the finger one row per row height; past the ends of a wheel that doesn't
 *            loop it stretches with resistance
 *   fling    release velocity is projected forward and rounded to a row, then the wheel decays
 *            onto it exponentially, so it lands without a separate snap
 *   wheel    a mouse notch moves one row; trackpad scrolling turns it freely and settles when quiet
 *   tap      a row above or below the lens turns to the middle
 */

export const SLOTS = 18;
export const STEP = 360 / SLOTS;

export type DrumOptions = {
  count: number;
  loop: boolean;
  itemHeight: number;
  reduced: boolean;
  haptics: boolean;
  label: (index: number) => string;
  disabled: (index: number) => boolean;
  /** The wheel came to rest on this option. */
  onRest: (index: number) => void;
};

const mod = (n: number, m: number) => ((n % m) + m) % m;
const rubber = (x: number) => (1 - 1 / (x * 0.6 + 1)) / 0.6;

export function useWheelDrum(initial: number, options: DrumOptions) {
  const opts = React.useRef(options);
  React.useLayoutEffect(() => {
    opts.current = options;
  });
  const column = React.useRef<HTMLDivElement>(null);
  const drum = React.useRef<HTMLDivElement>(null);
  const lens = React.useRef<HTMLDivElement>(null);
  const faces = React.useRef<(HTMLElement | null)[]>([]);
  const lensFaces = React.useRef<(HTMLElement | null)[]>([]);
  const shown = React.useRef<number[]>([]);
  const sim = React.useRef({
    p: initial,
    from: initial,
    target: initial,
    tau: 0.3,
    t0: 0,
    settling: false,
    spring: false,
    rested: initial,
    tick: Math.round(initial),
    buzz: 0,
    touch: false,
  });
  const frame = React.useRef(0);

  const radius =
    options.itemHeight / (2 * Math.tan((STEP / 2) * (Math.PI / 180)));

  /** Write the drum's rotation and relabel the faces that crossed the back. */
  const paint = React.useCallback((force = false) => {
    const { count, loop, label, disabled, haptics } = opts.current;
    const s = sim.current;
    const r =
      opts.current.itemHeight / (2 * Math.tan((STEP / 2) * (Math.PI / 180)));
    const transform = `translateZ(${-r}px) rotateX(${s.p * STEP}deg)`;
    if (drum.current) drum.current.style.transform = transform;
    if (lens.current) lens.current.style.transform = transform;
    for (let k = 0; k < SLOTS; k++) {
      const i = k + SLOTS * Math.round((s.p - k) / SLOTS);
      if (!force && shown.current[k] === i) continue;
      shown.current[k] = i;
      const real = loop ? mod(i, count) : i;
      const empty = !loop && (i < 0 || i >= count);
      const text = empty || !count ? "" : label(real);
      const off = !empty && count > 0 && disabled(real);
      for (const el of [faces.current[k], lensFaces.current[k]]) {
        if (!el) continue;
        if (el.textContent !== text) el.textContent = text;
        el.toggleAttribute("data-off", off);
      }
    }
    // A tick under the finger for every row that passes the lens (phones that support it).
    const row = Math.round(s.p);
    if (row !== s.tick) {
      s.tick = row;
      const now = performance.now();
      if (
        haptics &&
        s.touch &&
        now - s.buzz > 45 &&
        typeof navigator !== "undefined" &&
        "vibrate" in navigator
      ) {
        s.buzz = now;
        try {
          navigator.vibrate(3);
        } catch {
          /* not allowed yet */
        }
      }
    }
  }, []);

  const rest = React.useCallback(() => {
    const { count, loop, disabled, onRest } = opts.current;
    const s = sim.current;
    s.settling = false;
    if (!count) return;
    const index = loop
      ? mod(Math.round(s.p), count)
      : Math.max(0, Math.min(count - 1, Math.round(s.p)));
    // Landed on an option that can't be chosen: turn on to the nearest one that can.
    if (disabled(index)) {
      for (let d = 1; d < count; d++) {
        const down = index - d,
          up = index + d;
        const ok = (i: number) =>
          (loop || (i >= 0 && i < count)) && !disabled(mod(i, count));
        const next = ok(down) ? down : ok(up) ? up : null;
        if (next !== null) {
          settleTo(Math.round(s.p) + (next - index), 0.16);
          return;
        }
      }
      return;
    }
    s.rested = index;
    onRest(index);
  }, []);

  const step = React.useCallback(
    function runStep(now: number) {
      frame.current = 0;
      const s = sim.current;
      if (!s.settling) return;
      const t = (now - s.t0) / 1000;
      let k: number;
      if (s.spring) {
        // Harmonic spring for overdrag boundaries (omega = 16, zeta = 0.74)
        const omega = 16,
          zeta = 0.74,
          damped = 10.76;
        k =
          Math.exp(-zeta * omega * t) *
          (Math.cos(damped * t) + (zeta / 0.6726) * Math.sin(damped * t));
        if (t > 0.44 || Math.abs(s.p - s.target) < 0.002) {
          s.p = s.target;
          paint();
          rest();
          return;
        }
      } else {
        k = Math.exp(-t / s.tau);
        if (Math.abs(s.p - s.target) < 0.002) {
          s.p = s.target;
          paint();
          rest();
          return;
        }
      }
      s.p = s.target + (s.from - s.target) * k;
      paint();
      frame.current = requestAnimationFrame(runStep);
    },
    [paint],
  );

  function settleTo(target: number, tau: number, spring = false) {
    const s = sim.current;
    s.from = s.p;
    s.target = target;
    s.tau = tau;
    s.spring = spring;
    s.t0 = performance.now();
    s.settling = true;
    if (opts.current.reduced) {
      s.p = target;
      paint();
      rest();
      return;
    }
    cancelAnimationFrame(frame.current);
    frame.current = requestAnimationFrame(step);
  }

  const clampTarget = (target: number) => {
    const { count, loop } = opts.current;
    return loop ? target : Math.max(0, Math.min(count - 1, target));
  };

  /** Turn to an option. Loops take the shorter way round. */
  const turnTo = React.useCallback(
    (index: number, animate = true) => {
      const { count, loop } = opts.current;
      const s = sim.current;
      if (!count) return;
      let target = index;
      if (loop) {
        const base = Math.round(s.settling ? s.target : s.p);
        const delta =
          mod(index - mod(base, count) + count / 2, count) - count / 2;
        target = base + Math.round(delta);
      }
      s.rested = mod(index, count);
      if (!animate) {
        cancelAnimationFrame(frame.current);
        frame.current = 0;
        s.settling = false;
        s.p = s.target = target;
        paint();
        return;
      }
      settleTo(target, 0.16);
    },
    [paint],
  );

  /** Move by whole rows from wherever the wheel is heading (keys, mouse notches). */
  const nudge = React.useCallback((rows: number) => {
    const s = sim.current;
    s.touch = false;
    const base = s.settling ? s.target : Math.round(s.p);
    settleTo(clampTarget(base + rows), 0.11);
  }, []);

  // Pointer, wheel and the initial paint.
  React.useEffect(() => {
    const el = column.current;
    if (!el) return;
    paint(true);
    let drag: {
      id: number;
      y: number;
      p: number;
      moved: boolean;
      samples: { y: number; t: number }[];
    } | null = null;
    let quiet: ReturnType<typeof setTimeout> | null = null;
    const s = sim.current;
    const H = () => opts.current.itemHeight;

    const down = (e: PointerEvent) => {
      if (e.button !== 0 || drag) return;
      el.setPointerCapture(e.pointerId);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      s.settling = false;
      s.touch = e.pointerType === "touch";
      drag = {
        id: e.pointerId,
        y: e.clientY,
        p: s.p,
        moved: false,
        samples: [{ y: e.clientY, t: e.timeStamp }],
      };
    };
    const move = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      const dy = e.clientY - drag.y;
      if (!drag.moved) {
        if (Math.abs(dy) < 3) return;
        drag.moved = true;
        drag.y = e.clientY;
      }
      drag.samples.push({ y: e.clientY, t: e.timeStamp });
      while (drag.samples.length > 2 && e.timeStamp - drag.samples[0].t > 90)
        drag.samples.shift();
      const { count, loop } = opts.current;
      let p = drag.p - (e.clientY - drag.y) / H();
      if (!loop) {
        if (p < 0) p = -rubber(-p);
        else if (p > count - 1) p = count - 1 + rubber(p - (count - 1));
      }
      s.p = p;
      paint();
    };
    const up = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      const d = drag;
      drag = null;
      if (!d.moved) {
        // A tap above or below the lens turns that row to the middle.
        const r = el.getBoundingClientRect();
        const r0 =
          opts.current.itemHeight /
          (2 * Math.tan((STEP / 2) * (Math.PI / 180)));
        const off =
          (Math.asin(
            Math.max(
              -1,
              Math.min(1, (e.clientY - (r.top + r.height / 2)) / r0),
            ),
          ) *
            180) /
          Math.PI /
          STEP;
        const rows = Math.round(off);
        if (rows) settleTo(clampTarget(Math.round(s.p) + rows), 0.16);
        else settleTo(clampTarget(Math.round(s.p)), 0.12);
        return;
      }
      const first = d.samples[0],
        last = d.samples[d.samples.length - 1];
      const fresh = e.timeStamp - last.t < 80 && last.t > first.t;
      const velocity = fresh
        ? -((last.y - first.y) / (last.t - first.t)) * (1000 / H())
        : 0; // rows per second
      const { count, loop } = opts.current;
      const outside = !loop && (s.p < 0 || s.p > count - 1);
      const projected = outside ? s.p : s.p + velocity * 0.3;
      const target = clampTarget(Math.round(projected));
      settleTo(
        target,
        outside ? 0.38 : Math.abs(target - s.p) < 0.75 ? 0.12 : 0.3,
        outside,
      );
    };
    const wheel = (e: WheelEvent) => {
      e.preventDefault();
      s.touch = false;
      const px =
        e.deltaMode === 1
          ? e.deltaY * H()
          : e.deltaMode === 2
            ? e.deltaY * H() * 5
            : e.deltaY;
      // A mouse wheel notch is one row; a trackpad turns the wheel freely and settles once it goes quiet.
      if (Math.abs(px) >= 50 && Number.isInteger(e.deltaY)) {
        nudge(Math.sign(px));
        return;
      }
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      s.settling = false;
      const { count, loop } = opts.current;
      let p = s.p + px / H();
      if (!loop) p = Math.max(-0.35, Math.min(count - 1 + 0.35, p));
      s.p = p;
      paint();
      if (quiet) clearTimeout(quiet);
      quiet = setTimeout(
        () => settleTo(clampTarget(Math.round(s.p)), 0.14),
        120,
      );
    };
    el.addEventListener("pointerdown", down);
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerup", up);
    el.addEventListener("pointercancel", up);
    el.addEventListener("wheel", wheel, { passive: false });
    return () => {
      if (quiet) clearTimeout(quiet);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      el.removeEventListener("pointerdown", down);
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerup", up);
      el.removeEventListener("pointercancel", up);
      el.removeEventListener("wheel", wheel);
    };
  }, []);

  // Options changed (a month with fewer days): relabel every face.
  const signature = `${options.count}|${options.loop}`;
  React.useEffect(() => {
    paint(true);
  }, [signature, paint]);

  const attachColumn = React.useCallback((el: HTMLDivElement | null) => {
    column.current = el;
  }, []);
  const attachDrum = React.useCallback((el: HTMLDivElement | null) => {
    drum.current = el;
  }, []);
  const attachLens = React.useCallback((el: HTMLDivElement | null) => {
    lens.current = el;
  }, []);
  const attachFace = React.useCallback((k: number, el: HTMLElement | null) => {
    faces.current[k] = el;
  }, []);
  const attachLensFace = React.useCallback(
    (k: number, el: HTMLElement | null) => {
      lensFaces.current[k] = el;
    },
    [],
  );

  return {
    column,
    drum,
    lens,
    faces,
    lensFaces,
    attachColumn,
    attachDrum,
    attachLens,
    attachFace,
    attachLensFace,
    radius,
    turnTo,
    nudge,
    repaint: () => paint(true),
    resting: () => sim.current.rested,
    moving: () => sim.current.settling,
  };
}

